const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const MAPS=[
 {id:'dust',name:'DUSTY DEPOT',sub:'DRY DOCKS',floor:'#8e7854',wall:'#ad915f',shade:'#594c35',sky:'#bca777',accent:'#e9c969',style:'dust'},
 {id:'neon',name:'NEON YARD',sub:'NIGHT SHIFT',floor:'#315050',wall:'#4b7870',shade:'#20413f',sky:'#162e35',accent:'#6ef0cf',style:'neon'},
 {id:'jungle',name:'JUNGLE RUN',sub:'CANOPY CAMP',floor:'#536343',wall:'#7e8d55',shade:'#3c4933',sky:'#273729',accent:'#c3d66c',style:'jungle'},
 {id:'ice',name:'FROST BITE',sub:'GLACIER BAY',floor:'#718d8a',wall:'#a7c7bc',shade:'#476268',sky:'#536a71',accent:'#e3ffe9',style:'ice'}
];
const PERKS=[
 {name:'Quickstep',type:'MOBILITY',desc:'Move 18% faster. Get to the good cover first.',key:'speed',icon:'↗'},
 {name:'Extra Padding',type:'SURVIVAL',desc:'Start each round with +30 paintball armor.',key:'health',icon:'♡'},
 {name:'Rapid Trigger',type:'WEAPON MOD',desc:'Fire 28% faster. Let the paint fly.',key:'fire',icon:'⌁'},
 {name:'Heavy Fill',type:'WEAPON MOD',desc:'Hits deal 35% more impact damage.',key:'damage',icon:'✳'},
 {name:'Extended Hopper',type:'WEAPON MOD',desc:'Carry 18 extra paintballs before reloading.',key:'ammo',icon:'▤'},
 {name:'Snap Loader',type:'WEAPON MOD',desc:'Reload 45% faster between volleys.',key:'reload',icon:'⟳'},
 {name:'Ghost Paint',type:'WEAPON MOD',desc:'Your shots travel faster and opponents see fewer splats.',key:'projectile',icon:'◉'},
 {name:'Shockwave',type:'TACTICAL',desc:'A direct hit briefly slows your rival.',key:'slow',icon:'ϟ'},
 {name:'Second Wind',type:'SURVIVAL',desc:'Recover 25 health when you score a hit.',key:'heal',icon:'+'},
 {name:'Wide Barrel',type:'WEAPON MOD',desc:'A forgiving spread makes close shots easier.',key:'spread',icon:'⌖'},
 {name:'Slide Kit',type:'MOBILITY',desc:'Sprint 35% faster and keep speed while turning.',key:'sprint',icon:'➤'},
 {name:'Paint Radar',type:'TACTICAL',desc:'A ping marks the rival through cover every 5 sec.',key:'radar',icon:'◎'}
];
let chosenMaps=['dust','neon','jungle'], targetRounds=5, mode='bot', mapIndex=0, round=1, score=[0,0], perks=[], perkCounts={}, gameOn=false, paused=false, lastTime=0, fireTimer=0, reloadTimer=0, ammo=12, opponentHealth=100, playerHealth=100, matchWinner=null, touchFire=false, isOnline=false, channel=null, pc=null, hostSide=false, remote={x:0,y:0,a:0,health:100,alive:true}, peerReady=false;
const canvas=$('#view'),ctx=canvas.getContext('2d');
// Arena tiles: 0 open, 1 wall, 2 low paint bunker.
const rawMaps={
 dust:['1111111111111111','1000000000000001','1000200002000001','1000200002000001','1000000000000001','1000002000000001','1020002000020001','1000000000000001','1000000000000001','1000200002000001','1000200002000001','1000000000000001','1000002000000001','1000000000000001','1000000000000001','1111111111111111'],
 neon:['1111111111111111','1000000000000001','1020000000002001','1000000000000001','1000200000020001','1000200000020001','1000000000000001','1020002000200001','1000000000000001','1000200000020001','1000200000020001','1000000000000001','1020000000002001','1000000000000001','1000000000000001','1111111111111111'],
 jungle:['1111111111111111','1000000000000001','1000200000000001','1000200002000001','1000000002000001','1020000000000001','1000002000000001','1000002000000001','1000000000000001','1000000000020001','1000000000020001','1000200000000001','1000200000200001','1000000000000001','1000000000000001','1111111111111111'],
 ice:['1111111111111111','1000000000000001','1020000000002001','1000000200000001','1000000200000001','1000200000020001','1000200000020001','1000000000000001','1000000000000001','1000200000020001','1000200000020001','1000000200000001','1020000000002001','1000000000000001','1000000000000001','1111111111111111']};
let grid,player={x:2.5,y:8,a:0},bot={x:13.5,y:8,a:Math.PI}, zbuffer=[];
function initMaps(){const host=$('#mapList');host.innerHTML='';MAPS.forEach(m=>{const el=document.createElement('button');el.className='map-card'+(chosenMaps.includes(m.id)?' selected':'');el.dataset.id=m.id;el.innerHTML=`<div class="map-art art-${m.style}"></div><small>${m.sub}</small><span>${m.name}</span>`;el.onclick=()=>{if(chosenMaps.includes(m.id)){if(chosenMaps.length===1)return;chosenMaps=chosenMaps.filter(x=>x!==m.id)}else chosenMaps.push(m.id);initMaps()};host.appendChild(el)});$('#mapCount').textContent=`${chosenMaps.length} selected`}
initMaps();$$('.choice').forEach(b=>b.onclick=()=>{$$('.choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');targetRounds=+b.dataset.rounds});
$('#botMode').onclick=()=>setMode('bot');$('#onlineMode').onclick=()=>setMode('online');function setMode(m){mode=m;$('#botMode').classList.toggle('active',m==='bot');$('#onlineMode').classList.toggle('active',m==='online');$('#onlinePanel').classList.toggle('hidden',m!=='online');$('#startBtn').classList.toggle('hidden',m==='online')}
function arena(){return MAPS.find(m=>m.id===chosenMaps[mapIndex%chosenMaps.length])||MAPS[0]}
function setArena(){grid=rawMaps[arena().id].map(row=>row.split('').map(Number));$('#arenaName').textContent=arena().name}
function startMatch(){round=1;score=[0,0];perks=[];perkCounts={};mapIndex=0;isOnline=mode==='online'&&peerReady;$('#lobby').classList.add('hidden');$('#game').classList.remove('hidden');newRound();canvas.requestPointerLock?.();}
$('#startBtn').onclick=startMatch;$('#quitBtn').onclick=()=>{gameOn=false;document.exitPointerLock?.();$('#game').classList.add('hidden');$('#lobby').classList.remove('hidden');$('#roundOverlay').classList.add('hidden')};
function newRound(){setArena();player={x:2.4,y:8,a:0};bot={x:13.5,y:8,a:Math.PI};remote={x:13.5,y:8,a:Math.PI,health:100,alive:true};playerHealth=100+(perkCounts.health?Math.min(60,perkCounts.health*30):0);opponentHealth=100;ammo=12+(perkCounts.ammo?perkCounts.ammo*18:0);fireTimer=0;reloadTimer=0;gameOn=true;paused=false;$('#roundOverlay').classList.add('hidden');$('#youHealth').style.width='100%';$('#enemyHealth').style.width='100%';$('#youScore').textContent=score[0];$('#enemyScore').textContent=score[1];$('#roundLabel').textContent=`ROUND ${String(round).padStart(2,'0')}`;$('#weaponName').textContent=perks.includes('damage')?'THE HEAVY FILL':perks.includes('fire')?'THE RAPID RENTAL':'THE RENTAL';$('#ammoLabel').textContent=`PAINTBALL / ${ammo}`;$('#streak').textContent=String(score[0]).padStart(2,'0');$('#hint').innerHTML=isOnline?'WASD MOVE <span>·</span> CLICK FIRE <span>·</span> SHIFT SPRINT':'WASD MOVE <span>·</span> CLICK FIRE <span>·</span> SHIFT SPRINT';toast(`${arena().name} — ROUND ${round}`);lastTime=performance.now();requestAnimationFrame(loop)}
function toast(t){const el=$('#toast');el.textContent=t;el.style.opacity=1;clearTimeout(el._timer);el._timer=setTimeout(()=>el.style.opacity=0,1700)}
function wall(x,y){const ix=Math.floor(x),iy=Math.floor(y);return !grid||iy<0||ix<0||iy>=grid.length||ix>=grid[0].length||grid[iy][ix]===1}
function blocked(x,y,r=.2){return wall(x-r,y-r)||wall(x+r,y-r)||wall(x-r,y+r)||wall(x+r,y+r)}
function norm(a){while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a}
function ray(px,py,angle){let d=0,hit=0,step=.035;while(d<18){d+=step;let x=px+Math.cos(angle)*d,y=py+Math.sin(angle)*d;if(wall(x,y)){hit=1;break}}return {d,hit,x:px+Math.cos(angle)*d,y:py+Math.sin(angle)*d,low:!hit&&grid[Math.floor(py+Math.sin(angle)*d)]?.[Math.floor(px+Math.cos(angle)*d)]===2}}
function resize(){const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function draw(){if(!grid)return;const w=innerWidth,h=innerHeight,m=arena(),cols=Math.ceil(w/3),fov=Math.PI/3,half=h*.53,ceil=ctx.createLinearGradient(0,0,0,h*.53);ceil.addColorStop(0,m.sky);ceil.addColorStop(1,m.shade);ctx.fillStyle=ceil;ctx.fillRect(0,0,w,h*.53);const floor=ctx.createLinearGradient(0,h*.48,0,h);floor.addColorStop(0,m.shade);floor.addColorStop(1,m.floor);ctx.fillStyle=floor;ctx.fillRect(0,h*.48,w,h*.52);
 // Painted floor lanes recede into perspective.
 ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle=m.accent;ctx.lineWidth=1;for(let i=-6;i<=6;i++){ctx.beginPath();ctx.moveTo(w/2+i*3,h*.51);ctx.lineTo(w/2+i*90,h);ctx.stroke()}for(let j=1;j<9;j++){let y=h*.51+(h*.49)*(j/9)**1.7;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.restore();zbuffer.length=cols;
 for(let x=0;x<cols;x++){const cam=(x/cols-.5)*fov,angle=player.a+cam,r=ray(player.x,player.y,angle),dist=r.d*Math.cos(cam);zbuffer[x]=dist;const wallH=Math.min(h*1.6,h/(dist*.72));const y=(h*.51-wallH/2);let shade=Math.max(.22,1-dist/13);if(r.low){ctx.fillStyle=`rgba(25,35,24,${.35+shade*.4})`;ctx.fillRect(x*3,y+wallH*.38,3,wallH*.62);ctx.fillStyle=m.wall;ctx.fillRect(x*3,y+wallH*.38,3,wallH*.06)}else {ctx.fillStyle=m.wall;ctx.globalAlpha=shade;ctx.fillRect(x*3,y,3,wallH);ctx.globalAlpha=1;if(Math.floor(r.x*2)%2===0){ctx.fillStyle='rgba(255,255,255,.055)';ctx.fillRect(x*3,y,3,wallH)}if((x%35)<3){ctx.fillStyle='rgba(10,15,10,.22)';ctx.fillRect(x*3,y,3,wallH)}}}
 // arena banners / colorful splatter marks
 for(let n=0;n<9;n++){let px=2+((n*7+3)%12)+.5,py=2+((n*5+4)%11)+.5;if(grid[Math.floor(py)]?.[Math.floor(px)]!==0)continue;let a=Math.atan2(py-player.y,px-player.x),diff=norm(a-player.a);if(Math.abs(diff)>fov*.52)continue;let d=Math.hypot(px-player.x,py-player.y),sx=w/2+diff/(fov/2)*(w/2),sy=h*.51,sz=Math.min(80,h/(d*1.3));if(d<zbuffer[Math.min(cols-1,Math.max(0,Math.floor(sx/3)))]+.3)continue;ctx.fillStyle=['#e55543','#d4ff39','#44b9a2'][n%3];ctx.globalAlpha=.65;ctx.beginPath();ctx.arc(sx,sy-sz*.7,sz*.18,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
 drawPlayer(isOnline?remote:bot,isOnline?'remote':'bot',w,h,fov,cols);drawGun(w,h);
}
function drawPlayer(target,kind,w,h,fov,cols){if(!target||target.alive===false)return;let dx=target.x-player.x,dy=target.y-player.y,d=Math.hypot(dx,dy),diff=norm(Math.atan2(dy,dx)-player.a);if(Math.abs(diff)>fov*.57)return;let sx=w/2+diff/(fov/2)*(w/2),zi=Math.min(cols-1,Math.max(0,Math.floor(sx/3)));if(d>zbuffer[zi]+.2)return;let size=Math.min(h*.8,h/(d*.82)),base=h*.52+size*.28,head=size*.17;const red=kind==='bot'||kind==='remote';ctx.save();ctx.translate(sx,base);ctx.shadowColor='#080a08';ctx.shadowBlur=10;ctx.fillStyle=red?'#ef674b':'#61d6a5';ctx.fillRect(-size*.2,-size*.53,size*.4,size*.52);ctx.fillStyle=red?'#f0c5a1':'#f0cf9f';ctx.beginPath();ctx.arc(0,-size*.65,head,0,Math.PI*2);ctx.fill();ctx.fillStyle=red?'#cb513e':'#b8e4ba';ctx.beginPath();ctx.arc(0,-size*.71,head*1.12,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#242925';ctx.fillRect(-size*.12,-size*.68,size*.24,head*.18);ctx.fillStyle='#20251f';ctx.fillRect(size*.14,-size*.49,size*.3,size*.07);ctx.fillStyle=mappingColor();ctx.fillRect(-size*.08,-size*.18,size*.16,size*.05);ctx.restore();}
function mappingColor(){return arena().accent}
function drawGun(w,h){let bob=Math.sin(performance.now()*.008)*(keys.has('w')||keys.has('s')?5:1);ctx.save();ctx.translate(w*.76,h*1.04+bob);ctx.rotate(-.08);ctx.fillStyle='#20251f';ctx.beginPath();ctx.moveTo(-80,0);ctx.lineTo(-53,-94);ctx.lineTo(57,-104);ctx.lineTo(100,0);ctx.closePath();ctx.fill();ctx.fillStyle='#637348';ctx.fillRect(-36,-85,91,23);ctx.fillStyle='#272d26';ctx.fillRect(23,-69,95,13);ctx.fillStyle=arena().accent;ctx.fillRect(-19,-91,30,4);ctx.fillStyle='#aab69d';ctx.fillRect(62,-65,11,4);ctx.restore()}

