const keys=new Set();addEventListener('keydown',e=>{if(['w','a','s','d',' ','ArrowLeft','ArrowRight'].includes(e.key.toLowerCase()))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key==='Escape'&&gameOn)paused=!paused});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('click',()=>{if(gameOn&&document.pointerLockElement!==canvas&&innerWidth>650)canvas.requestPointerLock?.();else if(gameOn)fire()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas)player.a=norm(player.a+e.movementX*.0024)});
let dragging=false;canvas.addEventListener('touchstart',e=>{if(e.touches.length){dragging=true;canvas._tx=e.touches[0].clientX;canvas._ty=e.touches[0].clientY}},{passive:true});canvas.addEventListener('touchmove',e=>{if(dragging&&e.touches.length){let t=e.touches[0],dx=t.clientX-canvas._tx;player.a=norm(player.a+dx*.008);canvas._tx=t.clientX;canvas._ty=t.clientY}},{passive:true});canvas.addEventListener('touchend',()=>dragging=false);$('#fireTouch').onpointerdown=e=>{e.preventDefault();touchFire=true;fire()};$('#fireTouch').onpointerup=()=>touchFire=false;$('#sprintTouch').onpointerdown=()=>keys.add('shift');$('#sprintTouch').onpointerup=()=>keys.delete('shift');
function fire(){if(!gameOn||paused||reloadTimer>0||fireTimer>0)return;if(ammo<=0){reloadTimer=perkCounts.reload?1.1:2.1;toast('RELOADING…');return}ammo--;$('#ammoLabel').textContent=`PAINTBALL / ${ammo}`;fireTimer=Math.max(.2,.48-(perkCounts.fire?.13:0));const t=isOnline?remote:bot,dx=t.x-player.x,dy=t.y-player.y,d=Math.hypot(dx,dy),diff=Math.abs(norm(Math.atan2(dy,dx)-player.a)),aim=(perkCounts.spread?.15:.07)+.01*d,occluded=ray(player.x,player.y,Math.atan2(dy,dx)).d<d-.35;if(diff<aim&&!occluded){const damage=25+(perkCounts.damage?9:0);if(isOnline){send({type:'hit',damage})}else {opponentHealth-=damage;if(perkCounts.heal)playerHealth=Math.min(100+perkCounts.health*30,playerHealth+8);showHit();$('#enemyHealth').style.width=Math.max(0,opponentHealth)+'%';if(opponentHealth<=0)endRound(true)}}else{const el=$('#hitMarker');el.classList.remove('show');void el.offsetWidth;el.classList.add('show')}if(ammo<=0)reloadTimer=perkCounts.reload?1.1:2.1}
function showHit(){const el=$('#hitMarker');el.classList.remove('show');void el.offsetWidth;el.classList.add('show');toast('SPLAT!')}
function botUpdate(dt){if(isOnline)return;const dx=player.x-bot.x,dy=player.y-bot.y,d=Math.hypot(dx,dy);bot.a=Math.atan2(dy,dx);bot.cool=(bot.cool||.7)-dt;bot.move=(bot.move||0)-dt;let visible=ray(bot.x,bot.y,bot.a).d>d-.4;if(bot.move<=0){bot.move=1+Math.random()*1.5;bot.strafe=(Math.random()-.5)*1.5}if(d>4||Math.random()<.008){const ang=bot.a+Math.PI/2*(bot.strafe||0),speed=.9;let nx=bot.x+Math.cos(ang)*speed*dt,ny=bot.y+Math.sin(ang)*speed*dt;if(!blocked(nx,bot.y,.2))bot.x=nx;if(!blocked(bot.x,ny,.2))bot.y=ny}if(bot.cool<=0){bot.cool=1.1+Math.random()*.55;if(visible&&d<10&&Math.random()<Math.max(.25,.78-d*.035)){playerHealth-=25;$('#youHealth').style.width=Math.max(0,playerHealth/Math.max(100,100+(perkCounts.health||0)*30)*100)+'%';toast('YOU GOT TAGGED');if(playerHealth<=0)endRound(false)}}}
function update(dt){fireTimer=Math.max(0,fireTimer-dt);if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){ammo=12+(perkCounts.ammo||0)*18;$('#ammoLabel').textContent=`PAINTBALL / ${ammo}`}}if(!gameOn||paused)return;let forward=(keys.has('w')?1:0)-(keys.has('s')?1:0),side=(keys.has('d')?1:0)-(keys.has('a')?1:0);const sprint=keys.has('shift'),speed=(sprint?3.9:2.5)*(perkCounts.speed?1.18:1)*(sprint&&perkCounts.sprint?1.35:1);let mag=Math.hypot(forward,side)||1;forward/=mag;side/=mag;let dx=(Math.cos(player.a)*forward-Math.sin(player.a)*side)*speed*dt,dy=(Math.sin(player.a)*forward+Math.cos(player.a)*side)*speed*dt;if(!blocked(player.x+dx,player.y,.2))player.x+=dx;if(!blocked(player.x,player.y+dy,.2))player.y+=dy;if(touchFire)fire();botUpdate(dt);if(isOnline){send({type:'state',x:player.x,y:player.y,a:player.a,health:playerHealth,alive:gameOn})}}
function loop(now){if(!gameOn)return;let dt=Math.min(.05,(now-lastTime)/1000||0);lastTime=now;update(dt);draw();requestAnimationFrame(loop)}
function endRound(won){if(!gameOn)return;gameOn=false;score[won?0:1]++;$('#youScore').textContent=score[0];$('#enemyScore').textContent=score[1];const majority=Math.ceil(targetRounds/2);matchWinner=score[0]>=majority?'you':score[1]>=majority?'rival':null;$('#resultKicker').textContent=won?'ROUND WON':'ROUND LOST';$('#resultTitle').textContent=won?'NICE SHOT.':'TAGGED OUT.';$('#resultText').textContent=matchWinner?(matchWinner==='you'?'You own this arena. Match point secured.':'Your rival takes the match. Run it back?'):`${score[0]} — ${score[1]}  /  ${matchWinner?'MATCH COMPLETE':'First to '+majority+' takes it'}`;const area=$('#perkArea');area.innerHTML='';if(!won&&!matchWinner){const picks=[...PERKS].sort(()=>Math.random()-.5).slice(0,3);area.innerHTML='<div class="perk-grid">'+picks.map((p,i)=>`<button class="perk-card" data-key="${p.key}"><small>${p.type} · 0${i+1}</small><strong>${p.icon} &nbsp;${p.name}</strong><p>${p.desc}</p></button>`).join('')+'</div>';area.querySelectorAll('.perk-card').forEach(el=>el.onclick=()=>{const key=el.dataset.key;perkCounts[key]=(perkCounts[key]||0)+1;perks.push(key);area.querySelectorAll('.perk-card').forEach(c=>c.disabled=true);area.innerHTML=`<div class="net-status">${PERKS.find(x=>x.key===key).name} equipped — the comeback starts now.</div>`;$('#nextBtn').classList.remove('hidden')});$('#nextBtn').classList.add('hidden')}else if(!matchWinner){area.innerHTML='<div class="net-status">You won this round. Keep your loadout.</div>'}else{$('#nextBtn').querySelector('span').textContent='PLAY AGAIN'}$('#roundOverlay').classList.remove('hidden');$('#nextBtn').onclick=()=>{if(matchWinner){$('#quitBtn').click();return}round++;mapIndex++;newRound()}}

