async function waitIce(pc){if(pc.iceGatheringState==='complete')return;await new Promise(resolve=>{const check=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',check);resolve()}};pc.addEventListener('icegatheringstatechange',check);setTimeout(resolve,7000)})}
function netState(text){$('#netStatus').textContent=text}
